	};
}

/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
export class CorruptJsonStore<T> implements JsonStore<T> {
	load(): JsonStoreLoadResult<T> {
		return { status: "corrupt" };
	}

	save(): JsonStoreSaveResult {
		return { status: "ok" };
